90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	    const TAG_PRINTABLE_STRING: u8 = 0x13;
118	    const TAG_BMP_STRING: u8 = 0x1E;
119	
120	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
121	    /// length encodings and truncated data.
122	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
123	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
124	        if tag & 0x1F == 0x1F {
125	            return Err("multi-byte tags are not supported".to_string());
126	        }
127	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
128	        let (len, header_len) = match first_len {
129	            0x00..=0x7F => (first_len as usize, 2),
130	            0x80 => return Err("indefinite length is not valid DER".to_string()),
131	            0xFF => return Err("reserved length byte".to_string()),
132	            long => {
133	                let n = (long & 0x7F) as usize;
134	                if !(1..=4).contains(&n) {
135	                    return Err("length is too large".to_string());
136	                }
137	                let bytes = buf
138	                    .get(2..2 + n)
139	                    .ok_or_else(|| "truncated long length".to_string())?;
140	                if bytes[0] == 0 {
141	                    return Err("non-minimal length encoding".to_string());
142	                }
143	                let mut len = 0usize;
144	                for &b in bytes {
145	                    len = len
146	                        .checked_shl(8)
147	                        .and_then(|l| l.checked_add(b as usize))
148	                        .ok_or_else(|| "length overflow".to_string())?;
149	                }
150	                if len < 0x80 {
151	                    return Err("non-minimal length encoding".to_string());
152	                }
153	                (len, 2 + n)
154	            }
155	        };
156	        let total = header_len
157	            .checked_add(len)
158	            .filter(|&t| t <= buf.len())
159	            .ok_or_else(|| "truncated TLV content".to_string())?;
160	        Ok((
161	            Tlv {
162	                tag,
163	                content: &buf[header_len..total],
164	            },
165	            &buf[total..],
166	        ))
167	    }
168	
169	    fn read_tagged<'a>(
170	        buf: &'a [u8],
171	        tag: u8,
172	        what: &str,
173	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
174	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
175	        if tlv.tag != tag {
176	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
177	        }
178	        Ok((tlv, rest))
179	    }
180	
181	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
182	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
183	        // signatureValue BIT STRING } — and nothing trailing.
184	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
185	        if !rest.is_empty() {
186	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
187	        }
188	
189	        let c = cert.content;
190	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
191	        let (outer_alg, c) = read_tagged(c, TAG_SEQUENCE, "outer signatureAlgorithm")?;
192	        let outer_alg = parse_signature_algorithm(outer_alg, "outer signatureAlgorithm")?;
193	        let (sig_value, c) = read_tlv(c)?;
194	        if sig_value.tag != TAG_BIT_STRING {
195	            return Err("signature must be a BIT STRING".to_string());
196	        }
197	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
198	            return Err("invalid signature BIT STRING".to_string());
199	        }
200	        if !c.is_empty() {
201	            return Err("trailing data in Certificate".to_string());
202	        }
203	
204	        // TBSCertificate ::= SEQUENCE {
205	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
206	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
207	        let t = tbs.content;
208	        let (first, t2) = read_tlv(t)?;
209	        let (version, t) = if first.tag == 0xA0 {
210	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
211	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
212	                return Err("invalid certificate version".to_string());
213	            }
214	            (ver.content[0], t2)
215	        } else {
216	            // No explicit version: v1 certificate.
217	            (0u8, t)
218	        };
219	
220	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
221	        let t = t3;
222	        let (tbs_alg, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
223	        let tbs_alg = parse_signature_algorithm(tbs_alg, "tbs signatureAlgorithm")?;
224	        if tbs_alg != outer_alg {
225	            return Err(mismatch_message(&outer_alg, &tbs_alg));
226	        }
227	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
228	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
229	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
230	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
231	        check_spki(spki)?;
232	        // Optional tail of TBSCertificate, in a fixed order:
233	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
234	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
235	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
236	        //                                             and the last field)
237	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
238	        // skipped, reordered or dropped. The extensions interior is decoded in
239	        // full by `check_extensions`; the unique IDs carry BIT STRING content
240	        // directly (implicit tagging), validated by `check_bit_string`.
241	        let mut t = t_after_spki;
242	        let mut issuer_uid_seen = false;
243	        let mut subject_uid_seen = false;
244	        let mut extensions_present = false;
245	        while !t.is_empty() {
246	            let tag_hint = t.first().copied();
247	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
248	                Some(0x81) => format!("issuerUniqueID: {e}"),
249	                Some(0x82) => format!("subjectUniqueID: {e}"),
250	                // A truncated field whose tag is already readable can still
251	                // be located: tag 0xA3 is the extensions field.
252	                Some(0xA3) => format!("extensions field: {e}"),
253	                _ => e,
254	            })?;
255	            match field.tag {
256	                0x81 | 0x82 => {
257	                    let what = if field.tag == 0x81 {
258	                        "issuerUniqueID"
259	                    } else {
260	                        "subjectUniqueID"
261	                    };
262	                    if version < 1 {
263	                        return Err(format!(
264	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
265	                        ));
266	                    }
267	                    if extensions_present {
268	                        return Err(format!(
269	                            "{what} must appear before the extensions field, \
270	                             which is the last field of tbsCertificate"
271	                        ));
272	                    }
273	                    if field.tag == 0x81 {
274	                        if issuer_uid_seen {
275	                            return Err("duplicate issuerUniqueID field".to_string());
276	                        }
277	                        if subject_uid_seen {
278	                            return Err(
279	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
280	                            );
281	                        }
282	                        issuer_uid_seen = true;
283	                    } else if subject_uid_seen {
284	                        return Err("duplicate subjectUniqueID field".to_string());
285	                    } else {
286	                        subject_uid_seen = true;
287	                    }
288	                    check_bit_string(field.content, what)?;
289	                }
290	                0xA1 | 0xA2 => {
291	                    let what = if field.tag == 0xA1 {
292	                        "issuerUniqueID"
293	                    } else {
294	                        "subjectUniqueID"
295	                    };
296	                    return Err(format!(
297	                        "{what} must be an implicitly tagged primitive BIT STRING \
298	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
299	                         and is not allowed",
300	                        field.tag - 0x20,
301	                        field.tag
302	                    ));
303	                }
304	                0xA3 => {
305	                    if extensions_present {
306	                        return Err("duplicate extensions field".to_string());
307	                    }
308	                    if version != 2 {
309	                        let name = if version == 0 {
310	                            "v1"
311	                        } else {
312	                            "v2"
313	                        };
314	                        return Err(format!(
315	                            "extensions are only allowed in v3 certificates, this is {name}"
316	                        ));
317	                    }
318	                    check_extensions(field.content)?;
319	                    extensions_present = true;
320	                }
321	                other => {
322	                    return Err(format!(
323	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
324	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
325	                         are allowed there, and extensions must be last"
326	                    ));
327	                }
328	            }
329	            t = rest;
330	        }
331	
332	        let serial_hex = format_serial(serial.content)?;
333	        let issuer = format_name(issuer, "issuer")?;
334	        let subject = format_name(subject, "subject")?;
335	
336	        let v = validity.content;
337	        let (nb, v2) = read_tlv(v)?;
338	        let (na, v3) = read_tlv(v2)?;
339	        if !v3.is_empty() {
340	            return Err("trailing data in validity".to_string());
341	        }
342	        let not_before = format_time(nb)?;
343	        let not_after = format_time(na)?;
344	
345	        Ok(Cert {
346	            subject,
347	            issuer,
348	            serial_hex,
349	            not_before,
350	            not_after,
351	        })
352	    }
353	
354	    /// Validate the content of the extensions field, i.e. the bytes wrapped
355	    /// by `[3] EXPLICIT`:
356	    ///
357	    /// ```text
358	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
359	    /// Extension  ::= SEQUENCE {
360	    ///   extnID    OBJECT IDENTIFIER,
361	    ///   critical  BOOLEAN DEFAULT FALSE,
362	    ///   extnValue OCTET STRING }
363	    /// ```
364	    ///
365	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
366	    /// Every extension must contain its OID and OCTET STRING in that order,
367	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
368	    /// Extension contents are never interpreted: unknown but well-formed
369	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
370	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
371	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
372	        if !rest.is_empty() {
373	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
374	        }
375	        if list.content.is_empty() {
376	            return Err("extensions SEQUENCE is empty".to_string());
377	        }
378	
379	        let mut buf = list.content;
380	        while !buf.is_empty() {
381	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
382	            buf = rest;
383	
384	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
385	            parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
386	
387	            // critical is optional; whatever stands between the OID and the
388	            // OCTET STRING must be exactly one BOOLEAN if it is present.
389	            let (maybe_bool, after_critical) = read_tlv(after_oid)
390	                .map_err(|e| format!("extension after OID: {e}"))?;
391	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
392	                match maybe_bool.content {
393	                    [0xFF] => {}
394	                    [0x00] => {
395	                        return Err(
396	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
397	                                .to_string()
398	                        )
399	                    }
400	                    _ => {
401	                        return Err(
402	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
403	                        )
404	                    }
405	                }
406	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
407	            } else {
408	                // Not a BOOLEAN: this element must itself be the extnValue.
409	                if maybe_bool.tag != TAG_OCTET_STRING {
410	                    return Err(format!(
411	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
412	                         got tag 0x{:02X}",
413	                        maybe_bool.tag
414	                    ));
415	                }
416	                (maybe_bool, after_critical)
417	            };
418	            // An empty OCTET STRING is legal; its bytes are not interpreted.
419	            let _ = octets.content;
420	            if !after_octets.is_empty() {
421	                return Err("trailing data in extension".to_string());
422	            }
423	        }
424	        Ok(())
425	    }
426	
427	    /// SubjectPublicKeyInfo ::= SEQUENCE {
428	    ///   algorithm        AlgorithmIdentifier,
429	    ///   subjectPublicKey BIT STRING }
430	    /// Nothing may be missing and no extra elements may follow.
431	    fn check_spki(spki: Tlv) -> Result<(), String> {
432	        let (alg, rest) = read_tagged(
433	            spki.content,
434	            TAG_SEQUENCE,
435	            "subjectPublicKeyInfo algorithm identifier",
436	        )?;
437	        check_algorithm_identifier(alg)?;
438	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
439	        check_bit_string(key.content, "subjectPublicKey")?;
440	        if !rest.is_empty() {
441	            return Err("trailing data in subjectPublicKeyInfo".to_string());
442	        }
443	        Ok(())
444	    }
445	
446	    /// AlgorithmIdentifier ::= SEQUENCE {
447	    ///   algorithm  OBJECT IDENTIFIER,
448	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
449	    /// The parameters, if present, must be exactly one complete DER TLV;
450	    /// absent parameters and an explicit NULL are both accepted. The
451	    /// parameter content is not interpreted for any particular algorithm.
452	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
453	        let (oid, rest) = read_tagged(alg.content, TAG_OID, "algorithm OID")?;
454	        parse_oid(oid.content).map_err(|e| format!("algorithm OID: {e}"))?;
455	        if rest.is_empty() {
456	            return Ok(());
457	        }
458	        let (_params, after) =
459	            read_tlv(rest).map_err(|e| format!("algorithm parameters: {e}"))?;
460	        if !after.is_empty() {
461	            return Err("multiple algorithm parameters".to_string());
462	        }
463	        Ok(())
464	    }
465	
466	    /// One of the certificate's two signature algorithm descriptions, kept as
467	    /// raw slices so two copies can be compared at the DER byte level: the OID
468	    /// content (arcs in their shortest encoding) and the complete parameter
469	    /// TLV (tag, length and content), or no parameter at all. An absent
470	    /// parameter and an explicit NULL are different representations.
471	    #[derive(Clone, Copy, PartialEq, Eq)]
472	    struct SignatureAlgorithm<'a> {
473	        oid_content: &'a [u8],
474	        params: Option<&'a [u8]>,
475	    }
476	
477	    /// Parse and fully validate one signatureAlgorithm SEQUENCE: it must start
478	    /// with one complete, shortest-encoded algorithm OID, followed by either
479	    /// nothing or exactly one complete DER parameter value. `loc` names which
480	    /// of the two copies is being checked ("outer signatureAlgorithm" or the
481	    /// copy inside tbsCertificate) and prefixes every error message.
482	    fn parse_signature_algorithm<'a>(
483	        alg: Tlv<'a>,
484	        loc: &str,
485	    ) -> Result<SignatureAlgorithm<'a>, String> {
486	        let (oid, rest) = read_tlv(alg.content).map_err(|e| format!("{loc}: {e}"))?;
487	        if oid.tag != TAG_OID {
488	            return Err(format!(
489	                "{loc}: algorithm must start with an OID (tag 0x06), got tag 0x{:02X}",
490	                oid.tag
491	            ));
492	        }
493	        // Validates the OID content itself: non-empty, complete base-128 arcs
494	        // in their shortest encoding.
495	        parse_oid(oid.content).map_err(|e| format!("{loc}: {e}"))?;
496	        let params = if rest.is_empty() {
497	            None
498	        } else {
499	            let (_param, after) = read_tlv(rest)
500	                .map_err(|e| format!("{loc}: algorithm parameters: {e}"))?;
501	            if !after.is_empty() {
502	                return Err(format!(
503	                    "{loc}: extra element after the algorithm parameters"
504	                ));
505	            }
506	            // Keep the full parameter TLV (tag, length and content), sliced
507	            // straight from the enclosing content; `read_tlv` already proved
508	            // it is a complete value.
509	            let param_len = rest.len() - after.len();
510	            Some(&rest[..param_len])
511	        };
512	        Ok(SignatureAlgorithm {
513	            oid_content: oid.content,
514	            params,
515	        })
516	    }
517	
518	    /// Describe the disagreement between the outer signatureAlgorithm and the
519	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
520	    /// fail to name the same algorithm or the same parameter representation.
521	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
522	        const OUTER: &str = "the outer signatureAlgorithm";
523	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
524	        if outer.oid_content != inner.oid_content {
525	            let outer_oid = parse_oid(outer.oid_content)
526	                .map(|arcs| arcs_to_string(&arcs))
527	                .unwrap_or_else(|_| "?".to_string());
528	            let inner_oid = parse_oid(inner.oid_content)
529	                .map(|arcs| arcs_to_string(&arcs))
530	                .unwrap_or_else(|_| "?".to_string());
531	            return format!(
532	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
533	                 names OID {inner_oid}"
534	            );
535	        }
536	        match (outer.params, inner.params) {
537	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
538	                format!(
539	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
540	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
541	                    hex_of(outer_params),
542	                    hex_of(inner_params),
543	                )
544	            }
545	            (Some(_), None) => format!(
546	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
547	                 (an absent parameter and an explicit value are different representations)"
548	            ),
549	            (None, Some(_)) => format!(
550	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
551	                 (an absent parameter and an explicit value are different representations)"
552	            ),
553	            // PartialEq already proved the copies unequal; reaching any other
554	            // arm here would be a logic error rather than a malformed cert.
555	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
556	                .to_string(),
557	        }
558	    }
559	
560	    fn hex_of(bytes: &[u8]) -> String {
561	        let mut s = String::with_capacity(bytes.len() * 2);
562	        for b in bytes {
563	            write!(s, "{b:02X}").unwrap();
564	        }
565	        s
566	    }
567	
568	    /// Validate the DER content of a BIT STRING: one leading byte counting
569	    /// unused bits (0..=7), and when the count is nonzero those low bits of
570	    /// the final data byte must all be zero. An empty bit string is only
571	    /// legal with a zero count.
572	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
573	        let unused = *content
574	            .first()
575	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
576	        if unused > 7 {
577	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
578	        }
579	        let data = &content[1..];
580	        if data.is_empty() {
581	            if unused != 0 {
582	                return Err(format!(
583	                    "{what} BIT STRING declares {unused} unused bits but has no data"
584	                ));
585	            }
586	            return Ok(());
587	        }
588	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
589	            return Err(format!(
590	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
591	            ));
592	        }
593	        Ok(())
594	    }
595	
596	    /// Render the serial number as upper-case hex, matching the integer value
597	    /// (a DER sign-padding 0x00 byte is not part of the number).
598	    fn format_serial(content: &[u8]) -> Result<String, String> {
599	        if content.is_empty() {
600	            return Err("empty serial number".to_string());
601	        }
602	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
603	            return Err("non-minimal serial number encoding".to_string());
604	        }
605	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
606	            return Err("non-minimal serial number encoding".to_string());
607	        }
608	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
609	            return Err("negative serial number".to_string());
610	        }
611	        let digits = if content.len() > 1 && content[0] == 0x00 {
612	            &content[1..]
613	        } else {
614	            content
615	        };
616	        let mut s = String::with_capacity(digits.len() * 2);
617	        for b in digits {
618	            write!(s, "{b:02X}").unwrap();
619	        }
620	        if s.is_empty() {
621	            s.push_str("00");
622	        }
623	        Ok(s)
624	    }
625	
626	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
627	    /// multi-valued RDNs joined with '+'). Values of known attribute types
628	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
629	    /// when their tag has a text decoder; a known type carrying any other
630	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
631	    /// name and uses the '#' form carrying the value's full DER encoding in
632	    /// hex. Attributes without a known short name use their dotted OID with
633	    /// the same '#' form.
634	    ///
635	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
636	    /// encodings must be sorted by their full encoding bytes (tag, then
637	    /// length, then content — the encoding, never the display name, dotted
638	    /// OID text or decoded value). The check is per RDN; it never reorders
639	    /// the members itself. `what` names the name being checked ("subject" or
640	    /// "issuer") so an ordering failure identifies it in the error message.
641	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
642	        let mut rdn_buf = name.content;
643	        let mut rdns: Vec<String> = Vec::new();
644	        while !rdn_buf.is_empty() {
645	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
646	            rdn_buf = rest;
647	
648	            let mut atv_buf = set.content;
649	            let mut parts = Vec::new();
650	            // Raw full encoding (tag, length and content) of each member of
651	            // this SET OF, straight from the certificate: DER SET OF ordering
652	            // compares the complete member encodings byte for byte. Equal
653	            // encodings may legitimately repeat and stay adjacent.
654	            let mut members: Vec<&[u8]> = Vec::new();
655	            while !atv_buf.is_empty() {
656	                let atv_start = atv_buf;
657	                let (atv, rest) =
658	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
659	                atv_buf = rest;
660	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
661	
662	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
663	                let (value, after_value) = read_tlv(after_oid)?;
664	                if !after_value.is_empty() {
665	                    return Err("trailing data in attribute value".to_string());
666	                }
667	
668	                let oid_arcs = parse_oid(oid.content)?;
669	
670	                // The value's own type rules apply before any display decision:
671	                // a PrintableString must hold only the RFC 5280 PrintableString
672	                // alphabet, and a BMPString must hold whole 16-bit BMP
673	                // characters, whether the attribute later renders as text for a
674	                // known short name or as '#'-hex for an unknown type. The hex
675	                // form must never let an illegal byte through, and an illegal
676	                // byte cannot be dropped or replaced. An empty value stays
677	                // legal. `what` names the offending name ("subject"/"issuer").
678	                if value.tag == TAG_PRINTABLE_STRING
679	                    && !is_printable_string(value.content)
680	                {
681	                    return Err(format!(
682	                        "{what} name: PrintableString attribute value contains an illegal \
683	                         character (only A-Z, a-z, 0-9, space and ' ( ) + , - . / : = ? are \
684	                         allowed)"
685	                    ));
686	                }
687	                if value.tag == TAG_BMP_STRING {
688	                    check_bmp_string(value.content, what)?;
689	                }
690	
691	                match oid_short_name(&oid_arcs) {
692	                    Some(label) => {
693	                        if is_text_value_tag(value.tag) {
694	                            // Supported string type: decode to escaped text.
695	                            // A decode failure (e.g. invalid UTF-8) means the
696	                            // certificate is corrupt; it must not be salvaged
697	                            // by falling back to the hex form.
698	                            let text = decode_attribute_value(value.tag, value.content)?;
699	                            parts.push(format!("{label}={}", escape_value(&text)));
700	                        } else {
701	                            // Known type but a legal value with no text decoder
702	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
703	                            // and show the full original DER encoding as '#'-hex.
704	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
705	                        }
706	                    }
707	                    None => {
708	                        // Unknown attribute type: RFC 4514 requires the form
709	                        // OID=#hex, where the hex is the full DER encoding
710	                        // (tag, length and content) of the attribute value.
711	                        // Showing the value as hex does not bypass its type
712	                        // rules: UTF8String content must be valid UTF-8, a
713	                        // PrintableString must keep to its alphabet and a
714	                        // BMPString must hold legal BMP characters, checks
715	                        // already performed above before this match.
716	                        if value.tag == 0x0C {
717	                            std::str::from_utf8(value.content)
718	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
719	                        }
720	                        let hex = value_hex(after_oid, after_value);
721	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
722	                    }
723	                }
724	            }
725	            if parts.is_empty() {
726	                return Err("empty RelativeDistinguishedName".to_string());
727	            }
728	            check_rdn_der_order(&members, what)?;
729	            rdns.push(parts.join("+"));
730	        }
731	        rdns.reverse();
732	        Ok(rdns.join(","))
733	    }
734	
735	    /// Validate one RDN as a DER SET OF: every member's complete
736	    /// AttributeTypeAndValue encoding must be less than or equal to the next
737	    /// one under ordinary byte ordering of tag, length and content. The
738	    /// comparison runs on the raw encodings only — CN/O short names, dotted
739	    /// OID text and decoded values never enter into it — and equal adjacent
740	    /// members (duplicate attributes) are allowed. The members are never
741	    /// reordered to make an unsorted input pass. `what` is "subject" or
742	    /// "issuer" and identifies the offending name in the error message.
743	    fn check_rdn_der_order(members: &[&[u8]], what: &str) -> Result<(), String> {
744	        for pair in members.windows(2) {
745	            if pair[0] > pair[1] {
746	                return Err(format!(
747	                    "{what} name: attributes of a multi-valued RelativeDistinguishedName \
748	                     are not encoded in DER SET OF order (the members must be sorted by \
749	                     their complete DER encoding bytes: tag, then length, then content)"
750	                ));
751	            }
752	        }
753	        Ok(())
754	    }
755	
756	    /// Uppercase hex of one complete value TLV, sliced straight from the
757	    /// input bytes (`around` ends at `rest`). The original tag and length
758	    /// bytes survive verbatim, including a legal long-form length; nothing is
759	    /// re-encoded and content alone is never emitted.
760	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
761	        let tlv_len = around.len() - rest.len();
762	        let mut hex = String::with_capacity(tlv_len * 2);
763	        for b in &around[..tlv_len] {
764	            write!(hex, "{b:02X}").unwrap();
765	        }
766	        hex
767	    }
768	
769	    /// Tags whose attribute values have a direct text decoding in
770	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
771	    /// legal non-text value for display purposes and is rendered as '#'-hex.
772	    fn is_text_value_tag(tag: u8) -> bool {
773	        matches!(
774	            tag,
775	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
776	        )
777	    }
778	
779	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
780	        if content.is_empty() {
781	            return Err("empty OID".to_string());
782	        }
783	        let mut arcs = Vec::new();
784	        // The first subidentifier encodes the first two arcs as
785	        // 40*first + second and is itself a base-128 quantity, so it can
786	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
787	        let mut i = 0;
788	        let first = read_oid_arc(content, &mut i)?;
789	        match first {
790	            0..=39 => {
791	                arcs.push(0);
792	                arcs.push(first);
793	            }
794	            40..=79 => {
795	                arcs.push(1);
796	                arcs.push(first - 40);
797	            }
798	            _ => {
799	                arcs.push(2);
800	                arcs.push(first - 80);
801	            }
802	        }
803	        while i < content.len() {
804	            arcs.push(read_oid_arc(content, &mut i)?);
805	        }
806	        Ok(arcs)
807	    }
808	
809	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
810	    /// continuation bytes and non-minimal encodings.
811	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
812	        let start = *i;
813	        let mut value = 0u64;
814	        loop {
815	            let b = *content
816	                .get(*i)
817	                .ok_or_else(|| "truncated OID arc".to_string())?;
818	            value = value
819	                .checked_mul(128)
820	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
821	                .ok_or_else(|| "OID arc overflow".to_string())?;
822	            *i += 1;
823	            if b & 0x80 == 0 {
824	                break;
825	            }
826	        }
827	        if *i - start > 1 && content[start] == 0x80 {
828	            return Err("non-minimal OID arc encoding".to_string());
829	        }
830	        Ok(value)
831	    }
832	
833	    fn arcs_to_string(arcs: &[u64]) -> String {
834	        arcs.iter()
835	            .map(u64::to_string)
836	            .collect::<Vec<_>>()
837	            .join(".")
838	    }
839	
840	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
841	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
842	        let name = match arcs {
843	            [2, 5, 4, 3] => "CN",
844	            [2, 5, 4, 4] => "SN",
845	            [2, 5, 4, 5] => "serialNumber",
846	            [2, 5, 4, 6] => "C",
847	            [2, 5, 4, 7] => "L",
848	            [2, 5, 4, 8] => "ST",
849	            [2, 5, 4, 9] => "STREET",
850	            [2, 5, 4, 10] => "O",
851	            [2, 5, 4, 11] => "OU",
852	            [2, 5, 4, 12] => "title",
853	            [2, 5, 4, 17] => "postalAddress",
854	            [2, 5, 4, 18] => "postalCode",
855	            [2, 5, 4, 20] => "telephoneNumber",
856	            [2, 5, 4, 42] => "givenName",
857	            [2, 5, 4, 43] => "initials",
858	            [2, 5, 4, 44] => "generationQualifier",
859	            [2, 5, 4, 46] => "dnQualifier",
860	            [2, 5, 4, 65] => "pseudonym",
861	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
862	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
863	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
864	            _ => return None,
865	        };
866	        Some(name)
867	    }
868	
869	    /// Whether every byte belongs to the RFC 5280 PrintableString alphabet:
870	    /// A-Z, a-z, 0-9, space, and ' ( ) + , - . / : = ?. Every other byte
871	    /// (including @, _, tabs, newlines, NUL and 0x80..=0xFF) is illegal.
872	    /// An empty value passes, preserving the existing acceptance of empty
873	    /// contents.
874	    fn is_printable_string(content: &[u8]) -> bool {
875	        content.iter().all(|&b| matches!(
876	            b,
877	            b'A'..=b'Z'
878	                | b'a'..=b'z'
879	                | b'0'..=b'9'
880	                | b' '
881	                | b'\''
882	                | b'('
883	                | b')'
884	                | b'+'
885	                | b','
886	                | b'-'
887	                | b'.'
888	                | b'/'
889	                | b':'
890	                | b'='
891	                | b'?'
892	        ))
893	    }
894	
895	    /// Validate BMPString content: an even number of bytes read as big-endian
896	    /// 16-bit characters, each of which must be a Basic Multilingual Plane
897	    /// code point (U+0000..=U+FFFF) and never a UTF-16 surrogate
898	    /// (U+D800..=U+DFFF). Surrogates are not characters, so a lone high or
899	    /// low surrogate is corrupt, and so is an adjacent pair that UTF-16
900	    /// rules would combine into an astral-plane character — the pair must
901	    /// not be merged and displayed. An illegal value fails the whole
902	    /// certificate; bytes are never dropped or replaced to salvage it.
903	    /// Empty content stays legal, preserving the existing acceptance of
904	    /// empty values. `what` names the name being checked ("subject" or
905	    /// "issuer") so the error identifies the offending name.
906	    fn check_bmp_string(content: &[u8], what: &str) -> Result<(), String> {
907	        if content.len() % 2 != 0 {
908	            return Err(format!(
909	                "{what} name: BMPString attribute value has an odd length of {} byte(s) \
910	                 (the content must be a sequence of 16-bit characters)",
911	                content.len()
912	            ));
913	        }
914	        for pair in content.chunks_exact(2) {
915	            let unit = u16::from_be_bytes([pair[0], pair[1]]);
916	            if (0xD800..=0xDFFF).contains(&unit) {
917	                return Err(format!(
918	                    "{what} name: BMPString attribute value contains the surrogate code \
919	                     point U+{unit:04X}, which is not a legal character (U+D800..=U+DFFF \
920	                     are not characters and cannot appear, alone or in pairs)"
921	                ));
922	            }
923	        }
924	        Ok(())
925	    }
926	
927	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
928	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
929	        let s = match tag {
930	            0x0C => std::str::from_utf8(content)
931	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
932	                .to_string(),
933	            // ASCII-family strings: every byte is also its Unicode code point.
934	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
935	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
936	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
937	            0x1E => {
938	                if content.len() % 2 != 0 {
939	                    return Err("odd-length BMPString".to_string());
940	                }
941	                // A BMPString character is one big-endian 16-bit BMP code
942	                // point, never a UTF-16 surrogate: surrogate pairs must not
943	                // be merged into astral-plane characters.
944	                let mut s = String::with_capacity(content.len() / 2);
945	                for c in content.chunks_exact(2) {
946	                    let unit = u16::from_be_bytes([c[0], c[1]]);
947	                    let ch = char::from_u32(unit as u32)
948	                        .ok_or_else(|| "surrogate code point in BMPString".to_string())?;
949	                    s.push(ch);
950	                }
951	                s
952	            }
953	            0x1C => {
954	                if content.len() % 4 != 0 {
955	                    return Err("invalid UniversalString length".to_string());
956	                }
957	                let mut s = String::new();
958	                for c in content.chunks_exact(4) {
959	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
960	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
961	                        return Err("invalid code point in UniversalString".to_string());
962	                    }
963	                    s.push(char::from_u32(cp).unwrap());
964	                }
965	                s
966	            }
967	            _ => {
968	                return Err(format!(
969	                    "unsupported attribute value string type (tag 0x{tag:02X})"
970	                ))
971	            }
972	        };
973	        Ok(s)
974	    }
975	
976	    /// RFC 4514 value escaping; everything above the ASCII control range
977	    /// (including CJK text) passes through unchanged.
978	    fn escape_value(value: &str) -> String {
979	        let mut out = String::with_capacity(value.len());
980	        let last = value.chars().count().saturating_sub(1);
981	        for (i, c) in value.chars().enumerate() {
982	            let at_edge = i == 0 || i == last;
983	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
984	                || (at_edge && (c == ' ' || c == '#'));
985	            if needs_backslash {
986	                out.push('\\');
987	                out.push(c);
988	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
989	                let mut buf = [0u8; 4];
990	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
991	                write!(out, "\\{b:02X}").unwrap();
992	            } else {
993	                out.push(c);
994	            }
995	        }
996	        out
997	    }
998	
999	    fn format_time(tlv: Tlv) -> Result<String, String> {
1000	        let (y, mo, d, h, mi, se) = match tlv.tag {
1001	            TAG_UTC_TIME => {
1002	                let c = tlv.content;
1003	                if c.len() != 13 || c[12] != b'Z' {
1004	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
1005	                }
1006	                let digits = &c[..12];
1007	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1008	                    return Err("non-numeric UTCTime".to_string());
1009	                }
1010	                let n = |a: usize, b: usize| -> u32 {
1011	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1012	                };
1013	                let yy = n(0, 1);
1014	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
1015	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
1016	            }
1017	            TAG_GENERALIZED_TIME => {
1018	                let c = tlv.content;
1019	                if c.len() != 15 || c[14] != b'Z' {
1020	                    return Err(
1021	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
1022	                    );
1023	                }
1024	                let digits = &c[..14];
1025	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1026	                    return Err("non-numeric GeneralizedTime".to_string());
1027	                }
1028	                let n = |a: usize, b: usize| -> u32 {
1029	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1030	                };
1031	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
1032	            }
1033	            other => return Err(format!("invalid time tag 0x{other:02X}")),
1034	        };
1035	        validate_datetime(y, mo, d, h, mi, se)?;
1036	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
1037	    }
1038	
1039	    fn validate_datetime(
1040	        year: i32,
1041	        month: u32,
1042	        day: u32,
1043	        hour: u32,
1044	        minute: u32,
1045	        second: u32,
1046	    ) -> Result<(), String> {
1047	        if !(1..=12).contains(&month) {
1048	            return Err("invalid month in certificate time".to_string());
1049	        }
1050	        if hour > 23 || minute > 59 || second > 59 {
1051	            return Err("invalid time of day in certificate time".to_string());
1052	        }
1053	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
1054	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
1055	        if day < 1 || day > days[(month - 1) as usize] {
1056	            return Err("invalid day in certificate time".to_string());
1057	        }
1058	        Ok(())
1059	    }
1060	}
