/// The structural rules every AlgorithmIdentifier in the certificate
/// follows: ...
struct AlgorithmIdentifier<'a> {
    oid_content: &'a [u8],
    params: Option<&'a [u8]>,
}

/// Which structural rule a malformed AlgorithmIdentifier violated, so each
/// reading position can word the failure in its own established way.
enum AlgIdError {
    ReadOid(String),
    OidTag(u8),
    BadOid(String),
    ReadParams(String),
    TrailingAfterParams,
}

fn parse_algorithm_identifier(alg: Tlv) -> Result<AlgorithmIdentifier, AlgIdError> {
    let (oid, rest) = read_tlv(alg.content).map_err(AlgIdError::ReadOid)?;
    if oid.tag != TAG_OID {
        return Err(AlgIdError::OidTag(oid.tag));
    }
    parse_oid(oid.content).map_err(AlgIdError::BadOid)?;
    let params = if rest.is_empty() {
        None
    } else {
        let (_param, after) = read_tlv(rest).map_err(AlgIdError::ReadParams)?;
        if !after.is_empty() {
            return Err(AlgIdError::TrailingAfterParams);
        }
        let param_len = rest.len() - after.len();
        Some(&rest[..param_len])
    };
    Ok(AlgorithmIdentifier { oid_content: oid.content, params })
}
