317	// ----- Assertions / process plumbing --------------------------------------
318	
319	fn assert_success(out: &Output) {
320	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
321	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
322	    assert_eq!(
323	        lossy(&out.stdout),
324	        format!(
325	            "Subject: {FIXED_SUBJECT}\n\
326	             Issuer: {FIXED_ISSUER}\n\
327	             Serial Number: {FIXED_SERIAL}\n\
328	             Not Before: {FIXED_NOT_BEFORE}\n\
329	             Not After: {FIXED_NOT_AFTER}\n"
330	        )
331	    );
332	}
333	
334	/// The malformed-input contract: exit code 2, nothing on stdout, and the
335	/// fixed invalid-certificate prefix on stderr followed by a reason that names
336	/// the expected location (`needle`: the outer copy, the tbsCertificate copy,
337	/// or their mismatch).
338	fn assert_invalid_at(out: &Output, needle: &str) {
339	    assert_eq!(
340	        out.status.code(),
341	        Some(2),
342	        "stdout={} stderr={}",
343	        lossy(&out.stdout),
344	        lossy(&out.stderr)
345	    );
346	    assert!(
347	        out.stdout.is_empty(),
348	        "stdout must be empty on failure, got: {}",
349	        lossy(&out.stdout)
350	    );
351	    let stderr = lossy(&out.stderr);
352	    let prefix = "chainview: invalid DER certificate: ";
353	    assert!(
354	        stderr.starts_with(prefix),
355	        "unexpected stderr: {stderr}"
356	    );
357	    let reason = &stderr[prefix.len()..];
358	    assert!(
359	        reason.contains(needle),
360	        "reason {reason:?} does not identify {needle:?}"
361	    );
362	}
363	
364	fn lossy(bytes: &[u8]) -> String {
365	    String::from_utf8_lossy(bytes).into_owned()
366	}
367	
368	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
369	    let cert = TempCert::new(tag, data);
370	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
371	        .arg("inspect")
372	        .arg(&cert.path)
373	        .output()
374	        .expect("running chainview");
375	    (output, cert)
376	}
377	
378	struct TempCert {
379	    path: PathBuf,
380	}
381	
382	impl TempCert {
383	    fn new(tag: &str, data: &[u8]) -> Self {
384	        static COUNTER: AtomicU64 = AtomicU64::new(0);
385	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
386	        let path = std::env::temp_dir().join(format!(
387	            "chainview-sigalg-test-{}-{tag}-{unique}.der",
388	            std::process::id()
389	        ));
390	        fs::write(&path, data).expect("writing temp certificate");
391	        TempCert { path }
392	    }
393	}
394	
395	impl Drop for TempCert {
396	    fn drop(&mut self) {
397	        let _ = fs::remove_file(&self.path);
398	    }
399	}
400	
401	// ----- Certificate / DER construction -------------------------------------
402	//
403	// The outer signatureAlgorithm and the copy inside tbsCertificate are
404	// supplied independently (already-encoded TLVs) so any damage or disagreement
405	// can be crafted while every enclosing wrapper keeps a correct length.
406	
407	fn build_cert(outer_alg: &[u8], tbs_alg: &[u8]) -> Vec<u8> {
408	    let spki_alg = alg_with_null_params(RSA_ENCRYPTION);
409	    build_cert_spki(outer_alg, tbs_alg, &spki_alg)
410	}
411	
412	fn build_cert_spki(outer_alg: &[u8], tbs_alg: &[u8], spki_alg: &[u8]) -> Vec<u8> {
413	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
414	    let validity = seq(&concat(&[
415	        &tlv(0x17, b"260115093000Z"),
416	        &tlv(0x17, b"270115093000Z"),
417	    ]));
418	    let subject = simple_cn_name("example.com");
419	    let issuer = simple_cn_name("Test CA");
420	    let spki = seq(&concat(&[spki_alg, &bit_string(&[0x00, 0x01, 0x00])]));
421	
422	    let tbs = seq(&concat(&[
423	        &serial,
424	        tbs_alg,
425	        &issuer,
426	        &validity,
427	        &subject,
428	        &spki,
429	    ]));
430	    seq(&concat(&[&tbs, outer_alg, &tlv(0x03, &[0x00])]))
431	}
432	
433	fn alg_with_oid_only(arcs: &[u64]) -> Vec<u8> {
434	    seq(&oid(arcs))
435	}
436	
437	fn alg_with_null_params(arcs: &[u64]) -> Vec<u8> {
438	    alg_with(arcs, &tlv(0x05, &[]))
439	}
440	
441	fn alg_with(arcs: &[u64], params: &[u8]) -> Vec<u8> {
442	    seq(&concat(&[&oid(arcs), params]))
443	}
444	
445	fn bit_string(content: &[u8]) -> Vec<u8> {
446	    tlv(0x03, content)
447	}
448	
449	fn simple_cn_name(cn: &str) -> Vec<u8> {
450	    let atv = seq(&concat(&[&oid(&[2, 5, 4, 3]), &tlv(0x0C, cn.as_bytes())]));
451	    let rdn = tlv(0x31, &atv);
452	    tlv(0x30, &rdn)
453	}
454	
455	/// TLV with caller-supplied length bytes; used to forge truncated or
456	/// non-minimal encodings.
457	fn raw_tlv(tag: u8, len_bytes: &[u8], content: &[u8]) -> Vec<u8> {
458	    let mut out = vec![tag];
459	    out.extend_from_slice(len_bytes);
460	    out.extend_from_slice(content);
461	    out
462	}
463	
464	fn oid(arcs: &[u64]) -> Vec<u8> {
465	    assert!(arcs.len() >= 2);
466	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
467	    for &arc in &arcs[2..] {
468	        content.extend_from_slice(&oid_arc(arc));
469	    }
470	    tlv(0x06, &content)
471	}
472	
473	fn oid_arc(mut value: u64) -> Vec<u8> {
474	    let mut out = vec![(value % 128) as u8];
475	    value /= 128;
476	    while value > 0 {
477	        out.push(0x80 | (value % 128) as u8);
478	        value /= 128;
479	    }
480	    out.reverse();
481	    out
482	}
483	
484	fn seq(content: &[u8]) -> Vec<u8> {
485	    tlv(0x30, content)
486	}
487	
488	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
489	    let mut out = vec![tag];
490	    out.extend_from_slice(&der_len(content.len()));
491	    out.extend_from_slice(content);
492	    out
493	}
494	
495	fn der_len(n: usize) -> Vec<u8> {
496	    if n < 0x80 {
497	        vec![n as u8]
498	    } else {
499	        let mut body = Vec::new();
500	        let mut v = n;
501	        while v > 0 {
502	            body.push((v & 0xFF) as u8);
503	            v >>= 8;
504	        }
505	        body.reverse();
506	        let mut out = vec![0x80 | body.len() as u8];
507	        out.extend_from_slice(&body);
508	        out
509	    }
510	}
511	
512	fn concat(parts: &[&[u8]]) -> Vec<u8> {
513	    let mut out = Vec::new();
514	    for part in parts {
515	        out.extend_from_slice(part);
516	    }
517	    out
518	}
